            slug?: string;
            title?: string;
            summary?: string;
            description?: string;
            category?: string;
            /**
             * @description What this listing actually is. Empty on the listings that predate the vocabulary — the column is nullable so they keep selling — and mandatory before it can be published again.
             * @example scuba
             */
